// A camera-shaped JPEG of 66,713 bytes: SOI; an APP1 Exif segment of 4,098 bytes (a big-endian TIFF header, IFD0 at
// 8 with one orientation entry and no next IFD, then padding), which sends JPEGDEC's header parse past its 2 KiB
// buffer to a seek; two COM segments of 31,002 bytes, each another seek; then JPEG_BASELINE after its SOI (APP0 to
// EOI). The layout walk passes it, and it decodes as JPEG_BASELINE does.
inline std::vector<uint8_t> bigExifJpeg() {
  std::vector<uint8_t> file = {0xFF, 0xD8};
  const auto segment = [&file](const uint8_t marker, const std::vector<uint8_t>& body) {
    const size_t length = body.size() + 2;
    file.insert(file.end(), {0xFF, marker, static_cast<uint8_t>(length >> 8), static_cast<uint8_t>(length)});
    file.insert(file.end(), body.begin(), body.end());
  };
  std::vector<uint8_t> exif = {'E',  'x',  'i', 'f', 0, 0,                    // the Exif header
                               'M',  'M',  0,   42,  0, 0, 0, 8,              // TIFF: big-endian, IFD0 at 8
                               0,    1,                                       // IFD0: one entry
                               0x01, 0x12, 0,   3,   0, 0, 0, 1, 0, 1, 0, 0,  // orientation (274), short, 1
                               0,    0,    0,   0};                           // no next IFD
  exif.resize(4096, 0x5A);
  segment(0xE1, exif);
  segment(0xFE, std::vector<uint8_t>(31000, 'c'));
  segment(0xFE, std::vector<uint8_t>(31000, 'd'));
  file.insert(file.end(), JPEG_BASELINE + 2, JPEG_BASELINE + sizeof(JPEG_BASELINE));
  return file;
}
